356	                  );
357	                })}
358	              </div>
359	            ) : (
360	              <div className="text-center py-16 flex flex-col items-center flex-1 justify-center rounded-2xl border border-white/5 bg-white/5">
361	                <Users className="w-12 h-12 mb-4 text-white/20" />
362	                <p className="text-lg font-bold text-white/70">No teams found</p>
363	                <p className="text-sm text-white/40 mt-2 max-w-sm text-center">
364	                  {searchQuery 
365	                    ? "No teams match your search query." 
366	                    : "There are no teams submitted for this competition category yet."}
367	                </p>
