379	            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
380	            
381	            <motion.div 
382	              className="bg-[#0f0f0f] border border-purple-500/30 rounded-3xl w-full max-w-xl shadow-2xl relative my-8"
383	              initial={{ scale: 0.95, y: 20 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.95, y: 20 }}
384	              transition={{ type: 'spring', damping: 25, stiffness: 300 }}>
385	              
386	              {/* If we already made a selection once, we can cancel changing it */}
387	              {selectedCompetitionType && isSelectionComplete && (
388	                <button 
389	                  onClick={() => setShowModal(false)}
390	                  className="absolute top-6 right-6 w-8 h-8 rounded-full bg-white/5 hover:bg-white/10 flex items-center justify-center text-white/50 hover:text-white transition-colors">
391	                  <X className="w-4 h-4" />
392	                </button>
393	              )}
394	
395	              <div className="p-8 space-y-8">
396	                <div className="text-center">
397	                  <div className="w-12 h-12 rounded-2xl bg-purple-500/20 flex items-center justify-center mx-auto mb-4 border border-purple-500/30">
398	                    <Filter className="w-6 h-6 text-purple-400" />
399	                  </div>
400	                  <h2 className="text-2xl font-black text-white">Select Judging Category</h2>
401	                  <p className="text-white/50 text-sm mt-2">Choose the competition context you are judging for right now.</p>
402	                </div>
403	
404	                {/* Fixed Assignments */}
405	                <div className="rounded-xl border border-white/10 bg-white/5 p-4 flex justify-around">
406	                  <div className="text-center">
407	                    <p className="text-[10px] font-bold tracking-widest uppercase text-white/40 mb-1">Assigned Gender</p>
408	                    <p className="font-bold text-white">{judgeInfo.gender}</p>
409	                  </div>
