421	                    {competitionTypes
422	                      .filter(ct => !judgeInfo.competitionTypes || judgeInfo.competitionTypes.includes(ct.value))
423	                      .map(ct => (
424	                        <SelectBtn key={ct.value} selected={selectedCompetitionType === ct.value}
425	                          onClick={() => { 
