1	/**
2	 * Obfuscated Storage (HIGH-3 — short-term rename)
3	 *
4	 * ⚠️  THIS IS NOT A SECURITY BOUNDARY.
5	 *
6	 * This module wraps localStorage with client-side AES encryption keyed to
7	 * a browser fingerprint. It provides obfuscation — not security — because:
8	 *   1. The encryption key is derived entirely from public browser metadata.
9	 *   2. The key material is visible in the bundle source.
10	 *   3. Any script running in the same origin can read the same localStorage.
11	 *
12	 * The long-term fix (Phase 2, item 2.1) is to move tokens to httpOnly
13	 * cookies so they never appear in JavaScript-accessible storage at all.
14	 *
15	 * Renamed from `secureStorage` to `obfuscatedStorage` to make the actual
16	 * security posture explicit and prevent false confidence.
17	 */
18	import CryptoJS from 'crypto-js';
19	import { logger } from '@/infrastructure/logger.js';
20	
21	// Generate a more robust encryption key
22	const getEncryptionKey = () => {
23	  const envKey = import.meta.env.VITE_STORAGE_KEY || 'mallakhamb-india-2026';
24	  
25	  // Use multiple browser fingerprinting factors for better entropy
26	  const browserFingerprint = [
27	    navigator.userAgent.substring(0, 30),
28	    navigator.language || 'en',
29	    screen.colorDepth || '24',
30	    screen.width + 'x' + screen.height,
31	    new Date().getTimezoneOffset().toString()
32	  ].join('|');
33	  
34	  // Hash the fingerprint for consistent length
35	  const fingerprintHash = CryptoJS.SHA256(browserFingerprint).toString().substring(0, 32);
36	  
37	  return `${envKey}-${fingerprintHash}`;
38	};
39	
40	/**
41	 * Known per-role storage key suffixes.
42	 * When clearing for a specific role we remove `${role}_${suffix}` keys.
43	 */
44	const ROLE_KEY_SUFFIXES = ['token', 'user'];
45	
46	export const obfuscatedStorage = {
47	  setItem: (key, value) => {
48	    try {
49	      const encrypted = CryptoJS.AES.encrypt(value, getEncryptionKey()).toString();
50	      localStorage.setItem(key, encrypted);
51	    } catch (error) {
52	      logger.error('Failed to encrypt data:', error);
53	      // Do not fall back to plain storage - fail silently to avoid exposing sensitive data
54	    }
55	  },
56	  
57	  getItem: (key) => {
58	    try {
59	      const encrypted = localStorage.getItem(key);
60	      if (!encrypted) return null;
61	      
62	      const decrypted = CryptoJS.AES.decrypt(encrypted, getEncryptionKey());
63	      const value = decrypted.toString(CryptoJS.enc.Utf8);
64	      return value || null;
65	    } catch (error) {
66	      logger.error('Failed to decrypt data:', error);
67	      return null; // Do not fall back to plain storage
68	    }
69	  },
70	  
71	  removeItem: (key) => {
72	    localStorage.removeItem(key);
73	  },
74	
75	  /**
76	   * Remove only the storage keys belonging to a specific role.
77	   * Other roles' sessions are preserved so concurrent logins survive.
78	   *
79	   * @param {string} role - The role to clear (e.g. 'admin', 'superadmin')
80	   */
81	  clearForRole: (role) => {
82	    if (!role) return;
83	    for (const suffix of ROLE_KEY_SUFFIXES) {
84	      localStorage.removeItem(`${role}_${suffix}`);
85	    }
86	    // Also clear any legacy un-prefixed keys
87	    localStorage.removeItem('token');
88	    localStorage.removeItem('user');
89	    localStorage.removeItem('userType');
90	  },
91	
92	  /**
93	   * Nuclear clear — removes ALL localStorage keys.
94	   * Prefer clearForRole() in logout flows to preserve other sessions.
95	   */
96	  clear: () => {
97	    localStorage.clear();
98	  }
99	};
100	
101	/**
102	 * @deprecated Use `obfuscatedStorage` instead. This alias exists only for
103	 * backward compatibility during migration and will be removed in Phase 2.
104	 */
105	export const secureStorage = obfuscatedStorage;
