47	  const segment = roleMatch[1].toLowerCase();
48	  const roleMap = {
49	    admin: 'admin',
50	    superadmin: 'superadmin',
51	    'super-admin': 'superadmin',
52	    coach: 'coach',
53	    player: 'player',
54	    judge: 'judge',
55	  };
56	  
57	  return roleMap[segment] || 'admin';
58	};
