62	 * @param {string} role - The user role (admin, superadmin, coach, player, judge)
63	 * @returns {Object} Configuration object with UI elements, icons, and navigation paths
64	 */
65	const getRoleConfig = (role) => {
66	  // Unified ornament component - same design for all roles, only color changes
67	  const UnifiedOrnament = ({ color }) => (
68	    <motion.div className="relative flex items-center justify-center"
69	      initial={{ opacity: 0, scale: 0.6 }}
70	      animate={{ opacity: 1, scale: 1 }}
71	      transition={{ duration: 0.9, delay: 0.3, type: 'spring', stiffness: 200, damping: 18 }}>
72	      <motion.div className="absolute w-24 h-24 rounded-full border"
73	        style={{ borderColor: `${color}30` }}
74	        animate={{ scale: [1, 1.06, 1], opacity: [0.6, 1, 0.6] }}
75	        transition={{ duration: 3, repeat: Infinity, ease: 'easeInOut' }} />
76	      <div className="relative w-20 h-20 rounded-2xl flex items-center justify-center"
