167	  const [showCompetitionSelection, setShowCompetitionSelection] = useState(false);
168	  const [lockoutEndTime, setLockoutEndTime] = useState(null);
169	  const [rateLimitEndTime, setRateLimitEndTime] = useState(null);
170	  const [loginError, setLoginError] = useState(null);
171	  
172	  // Clear lockout/rate limit when timer expires
173	  useEffect(() => {
174	    if (lockoutEndTime) {
175	      const checkLockout = setInterval(() => {
