179	        }
180	      }, 1000);
181	      return () => clearInterval(checkLockout);
182	    }
183	  }, [lockoutEndTime]);
184	  
185	  useEffect(() => {
186	    if (rateLimitEndTime) {
187	      const checkRateLimit = setInterval(() => {
188	        if (new Date() >= rateLimitEndTime) {
189	          setRateLimitEndTime(null);
190	          clearInterval(checkRateLimit);
191	        }
192	      }, 1000);
193	      return () => clearInterval(checkRateLimit);
194	    }
195	  }, [rateLimitEndTime]);
196	  
197	  const { register, handleSubmit, formState: { errors }, setError } = useForm();
198	  const { checkRateLimit, recordAttempt, reset } = useRateLimit(5, 60000);
199	  
200	  // Clear login error when user starts typing
201	  useEffect(() => {
202	    if (loginError) {
203	      setLoginError(null);
