1	import { createContext, useContext, useState, useEffect, useCallback } from 'react';
2	import axios from 'axios';
3	import apiConfig from '@/config/api.config.js';
4	import { getTokenData } from '@/utils/auth/tokenUtils.js';
5	import { secureStorage } from '@/utils/auth/secureStorage.js';
6	import { logger } from '@/infrastructure/logger.js';
7	
8	const CompetitionContext = createContext();
9	
10	export const useCompetition = () => {
11	  const context = useContext(CompetitionContext);
12	  if (!context) {
13	    throw new Error('useCompetition must be used within a CompetitionProvider');
14	  }
15	  return context;
16	};
17	
18	export const CompetitionProvider = ({ children, userType }) => {
19	  // Debug logging
20	  useEffect(() => {
21	    logger.info('CompetitionProvider initialized', { userType });
22	  }, [userType]);
23	
24	  // Synchronously restore the last-selected competition from storage so the
25	  // navbar never flashes "Select" while the async fetch is in flight.
26	  const getStoredCompetition = (type) => {
27	    if (!type) return null;
28	    try {
29	      const stored = secureStorage.getItem(`${type}_current_competition`);
30	      return stored ? JSON.parse(stored) : null;
31	    } catch {
32	      return null;
33	    }
34	  };
35	
36	  const [currentCompetition, setCurrentCompetition] = useState(() => getStoredCompetition(userType));
37	  const [assignedCompetitions, setAssignedCompetitions] = useState([]);
38	  const [isLoading, setIsLoading] = useState(true);
39	  const [error, setError] = useState(null);
40	
41	  // Persist currentCompetition to storage whenever it changes so it survives navigation
42	  useEffect(() => {
43	    if (!userType) return;
44	    logger.info('CompetitionProvider: currentCompetition changed', { 
45	      userType, 
46	      hasCompetition: !!currentCompetition,
47	      competitionId: currentCompetition?._id,
48	      competitionName: currentCompetition?.name
49	    });
50	    if (currentCompetition && currentCompetition.name) {
51	      secureStorage.setItem(`${userType}_current_competition`, JSON.stringify(currentCompetition));
52	    } else if (!currentCompetition) {
53	      secureStorage.removeItem(`${userType}_current_competition`);
54	    }
55	  }, [currentCompetition, userType]);
56	
57	  // Helper to get token for current user type
58	  const getToken = useCallback(() => {
59	    if (!userType) return null;
60	    return secureStorage.getItem(`${userType}_token`);
61	  }, [userType]);
62	
63	  // Helper to extract competition ID from token (synchronous)
64	  const getCompetitionFromToken = useCallback(() => {
65	    const token = getToken();
66	    if (!token) return null;
67	    const decoded = getTokenData(token);
68	    return decoded?.competitionId || null;
69	  }, [getToken]);
70	
71	  /** Re-read on each render so effects re-run when JWT competitionId changes (e.g. after registration). */
72	  const competitionIdInToken = getCompetitionFromToken();
73	
74	  /**
75	   * Merge assigned list + current selection from token.
76	   * If the API list is briefly missing the JWT competition (e.g. right after register), use stored full object.
77	   */
78	  const finalizeAssignmentsFromApi = useCallback(
79	    (apiCompetitions) => {
80	      const competitionId = getCompetitionFromToken();
81	      let list = Array.isArray(apiCompetitions) ? [...apiCompetitions] : [];
82	
83	      if (competitionId && !list.some((c) => c._id === competitionId)) {
84	        const stored = getStoredCompetition(userType);
85	        if (stored?._id === competitionId) {
86	          list.push(stored);
87	          logger.info('finalizeAssignmentsFromApi: Merged stored competition into assigned list', {
88	            competitionId,
89	          });
90	        }
91	      }
92	
93	      setAssignedCompetitions(list);
94	
95	      if (competitionId) {
96	        const match = list.find((c) => c._id === competitionId);
97	        if (match) {
98	          setCurrentCompetition(match);
99	        } else {
100	          logger.warn('Competition from token not found in assigned list after merge', {
101	            competitionId,
102	            availableIds: list.map((c) => c._id),
103	          });
104	          setCurrentCompetition(null);
105	        }
106	      }
107	    },
108	    [userType, getCompetitionFromToken]
109	  );
110	
111	  /** Immediately add a competition to the dropdown and select it (e.g. after register + set-competition). */
112	  const mergeAssignedAndSelectCompetition = useCallback(
113	    (competition) => {
114	      const id = competition?._id || competition?.id;
115	      if (!userType || !id) return;
116	      const normalized = { ...competition, _id: id };
117	      setAssignedCompetitions((prev) => {
118	        const base = Array.isArray(prev) ? prev : [];
119	        if (base.some((c) => c._id === id || c.id === id)) return base;
120	        return [...base, normalized];
121	      });
122	      setCurrentCompetition(normalized);
123	      secureStorage.setItem(`${userType}_current_competition`, JSON.stringify(normalized));
124	    },
125	    [userType]
126	  );
127	
128	  // Fetch assigned competitions for the user (callable for manual refresh)
129	  const fetchAssignedCompetitions = useCallback(async () => {
130	    const token = getToken();
131	    if (!userType || !token || userType === 'judge') {
132	      logger.warn('fetchAssignedCompetitions: Skipping fetch', { userType, hasToken: !!token });
133	      return;
134	    }
135	
136	    logger.info('fetchAssignedCompetitions: Starting fetch', { userType });
137	
138	    try {
139	      setIsLoading(true);
140	      setError(null);
141	      const response = await axios.get(
142	        `${apiConfig.getBaseUrl()}/auth/competitions/assigned`,
143	        { headers: { Authorization: `Bearer ${token}`, ...apiConfig.getHeaders() } }
144	      );
145	      const responseData = response.data.data || response.data;
146	      const competitions = responseData.competitions || [];
147	      
148	      logger.info('fetchAssignedCompetitions: Competitions fetched', {
149	        count: competitions.length,
150	        competitionIds: competitions.map(c => c._id),
151	        competitionNames: competitions.map(c => c.name)
152	      });
153	      
154	      finalizeAssignmentsFromApi(competitions);
155	    } catch (err) {
156	      logger.error('Failed to fetch assigned competitions:', err);
157	      setError(err.response?.data?.message || 'Failed to load competitions');
158	    } finally {
159	      setIsLoading(false);
160	    }
161	  }, [userType, getToken, getCompetitionFromToken, finalizeAssignmentsFromApi]);
162	
163	  // Switch to a different competition
164	  const switchCompetition = useCallback(async (competitionId) => {
165	    if (!userType) throw new Error('User type is required to switch competition');
166	
167	    const token = getToken();
168	    if (!token) throw new Error('Authentication token not found');
169	
170	    if (isLoading) throw new Error('Competition switch already in progress');
171	
172	    try {
173	      setIsLoading(true);
174	      setError(null);
175	
176	      let competition = assignedCompetitions.find((c) => c._id === competitionId);
177	      if (!competition && currentCompetition?._id === competitionId) {
178	        competition = currentCompetition;
179	      }
180	      if (!competition && userType) {
181	        const stored = getStoredCompetition(userType);
182	        if (stored?._id === competitionId) competition = stored;
183	      }
184	      if (!competition) {
185	        throw new Error('Competition not found in assigned competitions');
186	      }
187	
188	      logger.info('switchCompetition: Starting switch', { 
189	        competitionId, 
190	        competitionName: competition.name,
191	        currentCompetitionId: currentCompetition?._id,
192	        currentCompetitionName: currentCompetition?.name
193	      });
194	
195	      // Make the API call to update the token FIRST (before optimistic update)
196	      const response = await axios.post(
197	        `${apiConfig.getBaseUrl()}/auth/set-competition`,
198	        { competitionId },
199	        { headers: { Authorization: `Bearer ${token}`, ...apiConfig.getHeaders() } }
200	      );
201	
202	      // Persist new token (now contains competitionId in payload)
203	      const newToken = response.data.data?.token || response.data.token;
204	      secureStorage.setItem(`${userType}_token`, newToken);
205	      logger.info('Competition switched successfully - token updated', { competitionId, competitionName: competition.name });
206	
207	      // NOW update state (this will trigger useEffect in components)
208	      setCurrentCompetition(competition);
209	      secureStorage.setItem(`${userType}_current_competition`, JSON.stringify(competition));
210	      logger.info('Competition state updated', { competitionId, competitionName: competition.name });
